L22:     try {
L23:         // The empty title argument keeps `start` from treating the URL as the
L24:         // window title on Windows.
L25:         const child = process.platform === "win32"
L26:             ? spawn("cmd.exe", ["/c", "start", "", url], {
L27:                 detached: true,
L28:                 stdio: "ignore",
L29:                 windowsHide: true,
L30:             })
